+      text: "Settings guards",
+      tone: "neutral",
+    });
+  }
+});
+
+test("only a template that is genuinely absent is called deleted", () => {
+  const deleted = guardBadge("gone", TEMPLATES);
+  assert.equal(deleted.tone, "danger");
